"""Static additive derivation of receipt guards, never runtime rewriting."""
import hashlib,sys
from pathlib import Path
R=Path(__file__).resolve().parents[2]
def fn(file,name,sql=False):
 s=(R/file).read_text();b=s.index('CREATE FUNCTION '+name+'(') if 'CREATE FUNCTION '+name+'(' in s else s.index('CREATE OR REPLACE FUNCTION '+name+'(');end=s.index('$$;',b)+3 if sql else s.index('END $$;',b)+len('END $$;');return s[b:end].replace('CREATE FUNCTION','CREATE OR REPLACE FUNCTION',1)
parts=[(R/'testing/D4/sql/recovery-core.sql').read_text()]
for file,name,sql,new in [('migrations-d4-proposed/V24__linear_multicount_checkpoints.sql','d4.multi_effects_safe',True,None),('migrations-d4-proposed/V19__sealed_checkpoint_continuation.sql','d4.continuation_safe',True,'d4.continuation_safe_before_i8'),('migrations-d4-proposed/V19__sealed_checkpoint_continuation.sql','d4.authorize_continuation',False,None),('migrations-d4-proposed/V21__checkpoint_laboratory_bridge.sql','d4.record_continuation_acceptance',False,None),('migrations-d4-proposed/V23__worker_execution_status.sql','d4.worker_execution_status',False,None)]:
 s=fn(file,name,sql).replace('FROM d2.effect_receipts','FROM d4.unresolved_receipts')
 if new:s=s.replace(name+'(',new+'(',1)
 if name=='d4.worker_execution_status':
  needle="OR EXISTS(SELECT 1 FROM d4.checkpoint_commands c WHERE"
  s=s.replace(needle,"OR EXISTS(SELECT 1 FROM d4.recovery_settlements rs JOIN d4.recovery_proofs rp ON rp.id=rs.proof_id WHERE rs.operation_id=op.id AND rs.generation=op.lease_generation AND rs.terminal AND rp.proof->>'attempt'=a.id::text AND d4.recovery_current(rs.id))\n   "+needle)
 parts+=['-- Derived from '+file+' SHA256 '+hashlib.sha256((R/file).read_bytes()).hexdigest(),s]
s=fn('migrations-d4-proposed/V25__checkpoint_boundary_guards.sql','d4.dispatch_continuation').replace("'d4.multi_heads'] LOOP","'d4.multi_heads','d4.recovery_proofs','d4.recovery_settlements','d4.recovery_observations'] LOOP")
parts.append(s)
parts.append("REVOKE ALL ON ALL TABLES IN SCHEMA d4 FROM PUBLIC;\nDO $$ DECLARE f record;BEGIN FOR f IN SELECT p.oid::regprocedure n FROM pg_proc p JOIN pg_namespace ns ON ns.oid=p.pronamespace WHERE ns.nspname='d4' AND (p.proname LIKE 'recovery_%' OR p.proname IN ('receipt_basis','receipt_resolved')) LOOP EXECUTE format('REVOKE ALL ON FUNCTION %s FROM PUBLIC',f.n);END LOOP;END $$;\n")
out='-- GENERATED by testing/D4/generate-recovery-admission.py; source SQL and old migrations remain reviewable.\n'+'\n\n'.join(parts);p=R/'migrations-d4-proposed/V26__conclusive_reconciliation.sql'
if '--check' in sys.argv:assert p.read_text()==out,'Recovery derivation differs'
else:p.write_text(out)
